<script setup>
import CustomSelect from '@/Components/CustomSelect.vue';
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import { Head, Link, useForm } from '@inertiajs/vue3';
import MiriCogIssueItems from '@/Components/MiriCogIssueItems.vue';
const props = defineProps({ movementTypes: Array, registerTypes: Array });
const headerFields = [['consignee_name','Consignee name'],['consignee_department','Consignee department'],['from_department','From department / company'],['from_location','From location'],['to_location','To'],['copy_to','Copy to'],['destination','Destination'],['receiver_email','Receiver email (optional)']];
const signers=[{name:'issued_by_name',title:'Issued & Checked By',designation:'issued_designation',date:'issued_date'},{name:'verified_by_name',title:'Verified By: HOD / Supervisor',designation:'verified_designation',date:'verified_date'},{name:'receiver_name',title:'Received By',designation:'receiver_designation',date:'received_date'}];
const form=useForm({movement_type:props.movementTypes[0],document_date:new Date().toLocaleDateString('en-CA'),...Object.fromEntries(headerFields.map(([k])=>[k,''])),...Object.fromEntries(signers.flatMap(s=>[[s.name,''],[s.designation,''],[s.date,'']])),remarks:'',items:[]});
const submit=()=>form.transform(data=>({...data,items:data.items.map(({row_key,batch_no,location,...row})=>row)})).post(route('miri-cogs.store'));
</script>
<template>
<Head title="Create Miri Internal Issue Note" />
<AuthenticatedLayout>
<form class="space-y-6" @submit.prevent="submit">
<header class="rounded-3xl border border-[#d8e7d4] bg-white p-6"><img src="/images/dayang-logo.png" alt="Dayang" class="h-14 w-auto" /><h1 class="mt-4 text-3xl font-bold text-[#234222]">Internal Issue Note</h1><p class="mt-2 text-sm text-slate-500">DE-F-07E · REV.0 · Internal Issue Note</p><p class="mt-4 rounded-xl bg-amber-50 p-3 text-sm text-amber-900">Equipment is reserved as soon as an outbound note is created, including drafts. Record Received backload before issuing it again, or cancel an unfulfilled draft. Paint closing stock is deducted when an outbound note is created and restored by tracked backloads or cancellation. CAN and LTR are tracked separately. TEC, Garnet & PPE stock changes only after Confirm stock movement on the saved COG. Verify opening balances first. Transfers require a matching destination stock record at the To location.</p></header>
<div v-if="Object.keys(form.errors).length" role="alert" class="rounded-xl bg-red-50 p-4 text-red-700"><p v-for="(error,k) in form.errors" :key="k">{{ error }}</p></div>
<section class="rounded-3xl border bg-white p-6"><h2 class="font-bold text-[#234222]">Document details</h2><div class="mt-4 grid gap-4 md:grid-cols-2 lg:grid-cols-3"><label class="text-sm">Movement type<CustomSelect v-model="form.movement_type" class="mt-2 w-full rounded-xl border-slate-200"><option v-for="type in movementTypes" :key="type">{{ type }}</option></CustomSelect></label><label class="text-sm">Date<input v-model="form.document_date" type="date" class="mt-2 w-full rounded-xl border-slate-200" required /></label><label v-for="[k,title] in headerFields" :key="k" class="text-sm">{{ title }}<input v-model="form[k]" :type="k==='receiver_email' ? 'email' : 'text'" class="mt-2 w-full rounded-xl border-slate-200" maxlength="255" /></label></div></section>
<MiriCogIssueItems v-model="form.items" :register-types="registerTypes" :movement-type="form.movement_type" />
<section class="rounded-3xl border bg-white p-6"><h2 class="font-bold text-[#234222]">Signatory details</h2><p class="mt-2 text-sm text-slate-500">Names are not signatures. Issued/verified boxes remain available for handwritten signing. Digital receiver signing is available after creation; this does not introduce a supervisor approval workflow.</p><div class="mt-5 grid gap-5 lg:grid-cols-3"><div v-for="s in signers" :key="s.name" class="space-y-3 rounded-xl border p-4"><h3 class="text-sm font-bold">{{ s.title }}</h3><label class="block text-sm">Name<input v-model="form[s.name]" :required="s.name==='issued_by_name'" class="mt-1 w-full rounded-lg border-slate-200" /></label><label class="block text-sm">Designation<input v-model="form[s.designation]" class="mt-1 w-full rounded-lg border-slate-200" /></label><label class="block text-sm">Date<input v-model="form[s.date]" type="date" class="mt-1 w-full rounded-lg border-slate-200" /></label></div></div><label class="mt-5 block text-sm">Document remarks<textarea v-model="form.remarks" rows="2" maxlength="1000" class="mt-2 w-full rounded-xl border-slate-200" /></label></section>
<div class="flex gap-3"><button class="btn bg-[#234222] text-white" :disabled="form.processing || !form.items.length">Create Internal Issue Note</button><Link :href="route('miri-cogs.index')" class="btn">Cancel</Link></div>
</form>
</AuthenticatedLayout>
</template>
